"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["367300"],{630058(e){e.exports=JSON.parse('{"tag":{"label":"survey","permalink":"/sdk/tags/survey","allTagsPath":"/sdk/tags","count":2,"items":[{"id":"api/assessment/assessment-api","title":"Assessment","description":"Creates a ServiceNow assessment/survey definition (asmtmetrictype) together with its categories (asmtmetriccategory) and questions/metrics (asmtmetric) as a single nested entity. The plugin wires the metrictype and category foreign keys automatically from the nesting structure, so you never set them by hand.","permalink":"/sdk/api/assessment/assessment-api"},{"id":"guides/assessment-guide","title":"Assessment & Survey Guide","description":"Guide for creating ServiceNow Assessments and Surveys (asmtmetrictype) using the Fluent API. Surveys collect user feedback through simple, unscored questionnaires; assessments evaluate, score, and rank assessable records with weighted and normalized results. Both share the same nested structure: type \u2192 categories \u2192 metrics \u2192 definitions. This framework only defines the survey/assessment and its in-platform delivery (a generated instance in the recipient\'s assessment queue) \u2014 it does not email a survey link or send a notification, so to send, email, or notify a recipient you must pair it with an Email Notification.","permalink":"/sdk/guides/assessment-guide"}],"unlisted":false}}')}}]);